	private static long openEnvironment(Path directory, int maxDbs) throws IOException {
		try (MemoryStack stack = stackPush()) {
			PointerBuffer pointer = stack.mallocPointer(1);
			E(mdb_env_create(pointer));
			long env = pointer.get(0);
			try {
				E(mdb_env_set_maxdbs(env, maxDbs));
				E(mdb_env_set_mapsize(env, 16L * 1024 * 1024));
				E(mdb_env_open(env, directory.toAbsolutePath().toString(),
						MDB_NOTLS | MDB_NOSYNC | MDB_NOMETASYNC, 0664));
				return env;
			} catch (IOException | RuntimeException | Error e) {
				mdb_env_close(env);
				throw e;
			}
		}
	}

	private static void putLegacyValue(MemoryStack stack, long txn, int dbi, long id, byte[] data)
			throws IOException {
		byte[] idKey = legacyIdKey(id);
		putRaw(stack, txn, dbi, data, idKey);
		putRaw(stack, txn, dbi, idKey, data);
	}

	private static void putRaw(MemoryStack stack, long txn, int dbi, byte[] key, byte[] value) throws IOException {
		MDBVal keyVal = MDBVal.calloc(stack);
		keyVal.mv_data(stack.bytes(key));
		MDBVal valueVal = MDBVal.calloc(stack);
		valueVal.mv_data(stack.bytes(value));
		E(mdb_put(txn, dbi, keyVal, valueVal, 0));
	}

	private static byte[] legacyIdKey(long id) {
		return concat(new byte[] { 4 }, varint(id));
	}

	private static byte[] namespaceData(String namespace) {
		return concat(new byte[] { 3 }, namespace.getBytes(StandardCharsets.UTF_8));
	}

	private static byte[] iriData(long namespaceId, String localName) {
		return concat(new byte[] { 0 }, varint(namespaceId), localName.getBytes(StandardCharsets.UTF_8));
	}

	private static byte[] literalData(long datatypeId, String label) {
		return concat(new byte[] { 1 }, varint(datatypeId), new byte[] { 0 },
				label.getBytes(StandardCharsets.UTF_8));
	}

	private static byte[] quad(long first, long second, long third, long fourth) {
		return concat(varint(first), varint(second), varint(third), varint(fourth));
	}

	private static byte[] varint(long value) {
		ByteBuffer buffer = ByteBuffer.allocate(1 + Long.BYTES);
		if (value == -1L) {
			// SQLite4's 9-byte unsigned representation used by the pre-explicit-datatype literal record.
			buffer.put((byte) 0xFF).putLong(-1L);
		} else {
			Varint.writeUnsigned(buffer, value);
		}
		return Arrays.copyOf(buffer.array(), buffer.position());
	}

	private static byte[] concat(byte[]... parts) {
		int length = Arrays.stream(parts).mapToInt(part -> part.length).sum();
		byte[] result = new byte[length];
		int offset = 0;
		for (byte[] part : parts) {
			System.arraycopy(part, 0, result, offset, part.length);
			offset += part.length;
		}
		return result;
	}

	private void writeLegacyMetadata() throws Exception {
		Files.writeString(dataDir.resolve("lmdbrdf.ver"), "5.3.2", StandardCharsets.UTF_8);
		Path triples = Files.createDirectories(dataDir.resolve("triples"));
		Properties properties = new Properties();
		properties.setProperty("version", "1");
		properties.setProperty("triple-indexes", "spoc,posc");
		try (OutputStream out = Files.newOutputStream(triples.resolve("triples.prop"))) {
			properties.store(out, "legacy test store");
		}
	}
